; DFMT.S - TEXT FORMATTING AND RENDERING PRIMITIVES

PRINTAT:
    ; INPUT: X = STRING POINTER LOW, Y = STRING POINTER HIGH
    ;        ZP $72 = ROW INDEX (5..19)
    ;        ZP $77 = COL INDEX (2..37)
    STX $75
    STY $76                 ; ZP $75/$76 POINTS TO SOURCE STRING
    
    LDA $72
    PHA                     ; SAVE ROW INDEX
    JSR COMPUTEROWADDR      ; COMPUTES SCREEN ADDRESS OF ROW TO ZP $73/$74
    PLA
    STA $72                 ; RESTORE ROW INDEX
    
    ; ADD COL INDEX (ZP $77) TO SCREEN POINTER ZP $73/$74
    LDA $73
    CLC
    ADC $77
    STA $73
    BCC _PANOCARRY
    INC $74
_PANOCARRY:
    
    ; COPY BYTES UNTIL $00
    LDY #0
_PACOPYLOOP:
    LDA ($75), Y
    BEQ _PADONE
    STA ($73), Y
    INY
    JMP _PACOPYLOOP
_PADONE:
    RTS

; FORMATHEX8 - FORMATS AN 8-BIT VALUE AS TWO UPPERCASE SCREEN-CODE HEX DIGITS.
;
; INPUT: A = BYTE VALUE.
; OUTPUT: FMTBUF, FMTBUF+1 = HEX DIGITS (HIGH NIBBLE FIRST). FMTBUF+2 = $00
;         TERMINATOR. (3 OF THE 5 FMTBUF BYTES USED.)
; CLOBBERS: A, Y. PRESERVES X.
FORMATHEX8:
    PHA
    LSR A
    LSR A
    LSR A
    LSR A                    ; A = HIGH NIBBLE
    TAY
    LDA HEXDIGITS, Y
    STA FMTBUF
    PLA
    AND #$0F                 ; A = LOW NIBBLE
    TAY
    LDA HEXDIGITS, Y
    STA FMTBUF+1
    LDA #0
    STA FMTBUF+2
    RTS

; FORMATHEX16 - FORMATS A 16-BIT VALUE AS FOUR UPPERCASE SCREEN-CODE HEX DIGITS.
;
; INPUT: X = VALUE LOW BYTE, Y = VALUE HIGH BYTE.
; OUTPUT: FMTBUF..FMTBUF+3 = HEX DIGITS (HIGH BYTE FIRST). FMTBUF+4 = $00
;         TERMINATOR. (ALL 5 FMTBUF BYTES USED.)
; CLOBBERS: A, X, Y.
FORMATHEX16:
    STX $78                  ; ZP $78 = VALUE LOW
    STY $79                  ; ZP $79 = VALUE HIGH
    LDA $79
    LSR A
    LSR A
    LSR A
    LSR A
    TAX
    LDA HEXDIGITS, X
    STA FMTBUF
    LDA $79
    AND #$0F
    TAX
    LDA HEXDIGITS, X
    STA FMTBUF+1
    LDA $78
    LSR A
    LSR A
    LSR A
    LSR A
    TAX
    LDA HEXDIGITS, X
    STA FMTBUF+2
    LDA $78
    AND #$0F
    TAX
    LDA HEXDIGITS, X
    STA FMTBUF+3
    LDA #0
    STA FMTBUF+4
    RTS

; FORMATDEC16 - FORMATS A 16-BIT UNSIGNED VALUE AS A RIGHT-ALIGNED DECIMAL
; FIELD, SPACE-PADDED TO A FIXED WIDTH OF 5.
;
; A FULL 16-BIT VALUE NEVER EXCEEDS 5 DECIMAL DIGITS (65535), SO THIS FIELD
; CANNOT OVERFLOW; THE FIXED-WIDTH RESULT FILLS ALL 5 FMTBUF BYTES WITH NO
; ROOM FOR A TERMINATOR. CALLERS WRITE THE 5 BYTES AS A BOUNDED FIXED-LENGTH
; FIELD (E.G. SCREENPUTSTRING WITH A MAXIMUM LENGTH OF 5), NOT AS A
; NUL-TERMINATED STRING.
;
; INPUT: X = VALUE LOW BYTE, Y = VALUE HIGH BYTE.
; OUTPUT: FMTBUF..FMTBUF+4 = 5 SCREEN-CODE BYTES, RIGHT-ALIGNED, SPACE-PADDED.
; CLOBBERS: A, X, Y.
FORMATDEC16:
    STX $78                  ; ZP $78/$79 = WORKING VALUE, DESTROYED BY DIV10
    STY $79
    LDA #$20                 ; PRE-FILL WITH SPACES (RIGHT-ALIGN PADDING)
    STA FMTBUF
    STA FMTBUF+1
    STA FMTBUF+2
    STA FMTBUF+3
    STA FMTBUF+4
    LDX #4                   ; WRITE INDEX, STARTS AT THE RIGHTMOST BYTE
FD16LOOP:
    JSR DIV10                ; DIVIDES $78/$79 BY 10 IN PLACE; REMAINDER IN A
    TAY
    LDA HEXDIGITS, Y          ; DIGITS 0-9 SHARE THE HEX DIGIT TABLE
    STA FMTBUF, X
    LDA $78
    ORA $79
    BEQ FD16DONE              ; QUOTIENT IS ZERO: NO MORE SIGNIFICANT DIGITS
    DEX
    BPL FD16LOOP              ; BOUNDED: 65535 NEEDS EXACTLY 5 DIGITS, X>=0
FD16DONE:
    RTS

; DIV10 - DIVIDES THE 16-BIT VALUE AT ZP $78/$79 BY 10, IN PLACE.
;
; BOUNDED BINARY LONG DIVISION: EXACTLY 16 SHIFT ITERATIONS REGARDLESS OF
; MAGNITUDE, NOT UNBOUNDED REPEATED SUBTRACTION.
;
; INPUT: ZP $78/$79 = DIVIDEND.
; OUTPUT: ZP $78/$79 = QUOTIENT. A = REMAINDER (0-9).
; CLOBBERS: A, X, ZP $7A.
DIV10:
    LDA #0
    STA $7A                  ; REMAINDER ACCUMULATOR
    LDX #16
DIV10LOOP:
    ASL $78
    ROL $79
    ROL $7A
    LDA $7A
    SEC
    SBC #10
    BCC DIV10SKIP
    STA $7A
    INC $78                  ; SET QUOTIENT BIT
DIV10SKIP:
    DEX
    BNE DIV10LOOP
    LDA $7A
    RTS
